pub fn test_prime(candidate: u64) -> bool {
    // By definition, primes are > 1. For safety we handle <= 1.
    if candidate <= 1 {
        return false;
    }
    // 2 and 3 are primes
    if candidate <= 3 {
        return true;
    }
    // Even numbers greater than 2 are not prime
    if candidate % 2 == 0 {
        return false;
    }
    // Test odd divisors from 3 up to sqrt(candidate).
    // We use `f <= candidate / f` to avoid overflow in f*f.
    let mut f = 3;
    while f <= candidate / f {
        if candidate % f == 0 {
            return false;
        }
        f += 2;
    }
    true
}

